const base = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const calls = [
  ["protections", "\"$HORIZON_BIN\" inbox list --mine --status open --kind protection --json"],
  ["unread-conversations", "\"$HORIZON_BIN\" inbox list --mine --status open --unread --kind conversation --comments 5 --json"],
  ["fence-I-1988", "\"$HORIZON_BIN\" inbox show I-1988 --no-mark-read --json"],
  ["roadmap-help", "\"$HORIZON_BIN\" roadmap list --help"],
  ["roadmap-project", "\"$HORIZON_BIN\" roadmap list --project Algebraic-Jacobian-Challenge-Rebuild --json"],
  ["tasks", "\"$HORIZON_BIN\" task list --project Algebraic-Jacobian-Challenge-Rebuild --json"],
  ["reviewer-task", "\"$HORIZON_BIN\" task show ajcr-reviewer-full --json"],
  ["process-hazard", "ps -eo pid,ppid,stat,etime,args | rg 'hgit status|git --git-dir=.*/workspace.git|index.lock'"]
];
const out = await Promise.all(calls.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:base, yield_time_ms:15000, max_output_tokens:30000});
  return `===== ${name} (exit ${r.exit_code ?? "running"}) =====\n${r.output}${r.session_id ? `\nSESSION_ID=${r.session_id}` : ""}`;
}));
out.forEach(text);

const base = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const calls = [
  ["protection-summaries", "\"$HORIZON_BIN\" inbox list --mine --status open --kind protection --json 2>/dev/null | jq '[.items[] | {id, title:(.body|split(\"\\n\")[0]), scope, audience, updated_at, last_comment:(.comments[-1].body // null)}]'"],
  ["fence", "\"$HORIZON_BIN\" inbox show I-1988 --no-mark-read --json 2>/dev/null | jq '{id,kind,status,labels,body,scope,audience,owner_task,metadata,comments}'"],
  ["inbox-health", "\"$HORIZON_BIN\" inbox list --mine --status open --json 2>/dev/null | jq '{total:(.items|length), non_protection:([.items[]|select(.kind != \"protection\")]|length), unread:([.items[]|select((.read_by|index(\"ajcr-alignment-tags\")) == null)]|length), by_kind:(.items|sort_by(.kind)|group_by(.kind)|map({kind:.[0].kind,count:length})), open_conversations:[.items[]|select(.kind==\"conversation\")|{id,title:(.body|split(\"\\n\")[0]),owner_task,audience,started_by:.metadata.started_by,read_by}]}'"],
  ["relevant-inbox", "\"$HORIZON_BIN\" inbox list --mine --status open --json 2>/dev/null | jq '[.items[] | select((.body|ascii_downcase|test(\"alignment|provenance|classification|to check|shared index|review-plan|pic0criticalpath|pic0galoisinvariantcomparison|pic0sepclosedjacobiandata|dashboard\"))) | {id,kind,title:(.body|split(\"\\n\")[0]),scope,audience,owner_task,updated_at}]'"],
  ["roadmap-top", "\"$HORIZON_BIN\" roadmap list --max-depth 1 --json 2>/dev/null | jq '.'"],
  ["roadmap-shape", "\"$HORIZON_BIN\" roadmap list --json 2>/dev/null | jq 'if type==\"array\" then {type:\"array\",count:length,first:.[0]} else {type:(type),keys:keys} end'"],
  ["index-state", "\"$HORIZON_GIT\" diff --cached --name-status HEAD; \"$HORIZON_GIT\" diff --cached --shortstat HEAD; find \"$HORIZON_LEDGER_GIT_DIR\" -maxdepth 1 -name 'index*' -printf '%f %s bytes %TY-%Tm-%TdT%TH:%TM:%TS\\n' | sort"],
  ["recent-concurrent", "\"$HORIZON_GIT\" log --format='%h|%cI|%(trailers:key=Archon-Task,valueonly)|%s' -12"]
];
const out = await Promise.all(calls.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:base, yield_time_ms:20000, max_output_tokens:20000});
  return `===== ${name} (exit ${r.exit_code ?? "running"}) =====\n${r.output}${r.session_id ? `\nSESSION_ID=${r.session_id}` : ""}`;
}));
out.forEach(text);

const base = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const calls = [
  ["unread-conversation", "\"$HORIZON_BIN\" inbox list --mine --status open --unread --kind conversation --json 2>/dev/null | jq '{attention:.attention.unread_conversations, items:[.items[]|{id,title:(.body|split(\"\\n\")[0]),audience,started_by:.metadata.started_by,comments:(.comments|length)}]}'"],
  ["global-health", "\"$HORIZON_BIN\" inbox list --status open --json 2>/dev/null | jq '{total:(.items|length), non_protection:([.items[]|select(.kind != \"protection\")]|length), by_kind:(.items|sort_by(.kind)|group_by(.kind)|map({kind:.[0].kind,count:length})), owned:([.items[]|select(.owner_task != \"\")]|map({id,kind,owner_task}))}'"],
  ["roadmap-ajcr", "\"$HORIZON_BIN\" roadmap list --json 2>/dev/null | jq '[.items[]|select(.projects|index(\"Algebraic-Jacobian-Challenge-Rebuild\"))] as $x | {count:($x|length), by_status:($x|sort_by(.status)|group_by(.status)|map({status:.[0].status,count:length})), by_kind:($x|sort_by(.kind)|group_by(.kind)|map({kind:.[0].kind,count:length})), roots:[$x[]|select(.parent==\"\")|{id,title,status,milestone}], review_plan:[$x[]|select(.id|startswith(\"AJCR.review-plan\"))|{id,title,status,priority,owner,parent,milestone}], warnings:.warnings}'"],
  ["issue-I-1646", "\"$HORIZON_BIN\" inbox show I-1646 --no-mark-read --json 2>/dev/null | jq '{id,kind,status,body,scope,comments}'"],
  ["issue-I-1922", "\"$HORIZON_BIN\" inbox show I-1922 --no-mark-read --json 2>/dev/null | jq '{id,kind,status,body,scope,comments}'"],
  ["issue-I-1986", "\"$HORIZON_BIN\" inbox show I-1986 --no-mark-read --json 2>/dev/null | jq '{id,kind,status,body,scope,comments}'"],
  ["issue-I-1987", "\"$HORIZON_BIN\" inbox show I-1987 --no-mark-read --json 2>/dev/null | jq '{id,kind,status,body,scope,comments}'"],
  ["worktree-scope", "\"$HORIZON_GIT\" diff --name-status HEAD -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild/blueprint MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian MainProjects/Algebraic-Jacobian-Challenge-Rebuild/hgraph .archon-horizon/roadmap .claude/skills/horizon/SKILL.md | awk '{c[$1]++; print} END {for (s in c) print \"COUNT\",s,c[s] > \"/dev/stderr\"}'"],
  ["untracked-scope", "\"$HORIZON_GIT\" ls-files --others --exclude-standard -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild/blueprint MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian MainProjects/Algebraic-Jacobian-Challenge-Rebuild/hgraph .archon-horizon/roadmap .claude/skills/horizon/SKILL.md | sed -n '1,240p'"]
];
const out = await Promise.all(calls.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:base, yield_time_ms:20000, max_output_tokens:25000});
  return `===== ${name} (exit ${r.exit_code ?? "running"}) =====\n${r.output}${r.session_id ? `\nSESSION_ID=${r.session_id}` : ""}`;
}));
out.forEach(text);

